<?php
use App\Http\Controllers\Admin\{BookingDocumentController as AdminBookingDocumentController,ServiceRequestController as AdminServiceRequestController,StayLifecycleController as AdminStayLifecycleController};
use App\Http\Controllers\UserArea\{BookingDocumentController,ServiceRequestController,StayLifecycleController}; use Illuminate\Support\Facades\Route;
Route::middleware(['auth','verified','azari.customer'])->prefix('account')->name('user.')->group(function(){Route::get('/bookings/{reference}/documents/{type}',BookingDocumentController::class)->name('bookings.documents');Route::post('/bookings/{reference}/check-in',[StayLifecycleController::class,'checkIn'])->name('bookings.check-in');Route::get('/service-requests',[ServiceRequestController::class,'index'])->name('service-requests.index');Route::post('/service-requests',[ServiceRequestController::class,'store'])->name('service-requests.store');Route::get('/service-requests/{serviceRequest}',[ServiceRequestController::class,'show'])->name('service-requests.show');});
Route::prefix('azari-admin')->name('azari.admin.')->middleware(['azari.staff'])->group(function(){Route::get('/bookings/{booking}/documents/{type}',AdminBookingDocumentController::class)->name('bookings.documents');Route::post('/bookings/{booking}/lifecycle/{action}',[AdminStayLifecycleController::class,'update'])->name('bookings.lifecycle');Route::get('/service-requests',[AdminServiceRequestController::class,'index'])->name('service-requests.index');Route::get('/service-requests/{serviceRequest}',[AdminServiceRequestController::class,'show'])->name('service-requests.show');Route::put('/service-requests/{serviceRequest}',[AdminServiceRequestController::class,'update'])->name('service-requests.update');});
